from json_pointer import *
from string_map import *
from json_document import *
def json_string_map_at(nodes: list[JsonValue], pointer: str) -> dict[str, str]:
    selected: int = json_pointer_index(nodes, pointer)
    if nodes[selected].kind != 5:
        raise ValueError
    values: dict[str, str] = {}
    index: int = selected + 1
    while index < len(nodes):
        node: JsonValue = nodes[index]
        if node.parent < selected:
            break
        if node.parent == selected:
            if node.kind != 3:
                raise ValueError
            values[node.key] = node.text
        index += 1
    return values

def json_string_map_parse(text: str) -> dict[str, str]:
    nodes = json_parse_document(text)
    return json_string_map_at(nodes, '')
